recipes.code:
{
  "inputs": [
    {
      "id": "kaidn-api-key",
      "type": "promptString",
      "description": "Your secret Kaidn API key, from https://kaidn.io",
      "password": true
    }
  ],
  "servers": {
    "kaidn": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@kaidn/mcp@0.2.2"
      ],
      "env": {
        "KAIDN_API_KEY": "${input:kaidn-api-key}",
        "KAIDN_API_URL": "https://api.kaidn.io",
        "KAIDN_MCP_ALLOW_WRITES": "<kaidn-mcp-allow-writes>",
        "KAIDN_MCP_MAX_QUOTA_CALLS": "100"
      }
    }
  }
}
